import{_ as t,o as e,c as i,a2 as r}from"./chunks/framework.DnrXFDHb.js";const c=JSON.parse('{"title":"AI 基础概念","description":"解释 AI、机器学习、深度学习、大模型、Token、上下文与参数等基础概念，建立后续学习所需的整体框架。","frontmatter":{"description":"解释 AI、机器学习、深度学习、大模型、Token、上下文与参数等基础概念，建立后续学习所需的整体框架。"},"headers":[],"relativePath":"ai/basics.md","filePath":"ai/basics.md","lastUpdated":1788693474000}'),l={name:"ai/basics.md"};function n(o,a,d,s,h,g){return e(),i("div",null,[...a[0]||(a[0]=[r(`<h1 id="ai-基础概念" tabindex="-1">AI 基础概念 <a class="header-anchor" href="#ai-基础概念" aria-label="Permalink to &quot;AI 基础概念&quot;">​</a></h1><blockquote><p><strong>一句话结论：</strong> AI、机器学习、深度学习是层层包含的概念，模型是训练得到的产物；训练阶段用数据调整参数，推理阶段用固定的参数处理新输入。模型的能力来自训练数据的统计规律，因此有明确的边界。</p></blockquote><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li>已阅读 <a href="/guide/getting-started">学习地图</a>，对知识库的整体结构有大致印象。</li><li>不要求编程经验，也不需要数学推导，本页只建立概念框架。</li><li>先接受一个边界：本页解释概念和关系，不涉及具体模型的选择与评测，那要等到后面的页面才展开。</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完后，你应该能够：</p><ul><li>用自己的话说明 AI、机器学习、深度学习和模型之间的包含关系。</li><li>区分训练和推理两个阶段，并判断一次日常使用属于哪个阶段。</li><li>解释 Token、上下文窗口和 Embedding 各自解决什么问题。</li><li>判断“参数量大”能说明什么、不能说明什么。</li><li>区分判别式与生成式两类模型，并判断一个任务属于哪一类。</li><li>说出模型能力边界的主要来源，以及一个 AI 系统除模型外还包含哪些环节。</li><li>识别关于 AI 的常见错误说法，并给出纠正理由。</li></ul><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="ai、机器学习、深度学习和模型是什么关系" tabindex="-1">AI、机器学习、深度学习和模型是什么关系 <a class="header-anchor" href="#ai、机器学习、深度学习和模型是什么关系" aria-label="Permalink to &quot;AI、机器学习、深度学习和模型是什么关系&quot;">​</a></h3><p>这四个词经常被混用，但它们不是并列关系，而是范围逐层收窄：</p><ul><li><strong>AI（Artificial Intelligence，人工智能）</strong>：最大的概念，指让机器完成通常需要人类智能的任务，例如理解语言、识别图像、做决策。早期也包括专家系统这类不依赖学习的方法。</li><li><strong>机器学习（Machine Learning）</strong>：AI 的一个子集。不由人逐条写死规则，而是让程序从数据中拟合规律。</li><li><strong>深度学习（Deep Learning）</strong>：机器学习的一个子集，使用多层神经网络（Neural Network）自动学习多层表示，是当前大模型和 AI 绘画的技术基础。</li><li><strong>模型（Model）</strong>：机器学习训练得到的产物，是一组学到的参数加上结构，用来对新输入做预测、分类或生成。</li></ul><p>可以用一条链概括日常见到的系统：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>实现 AI 的主流途径是机器学习 -&gt; 其中主流方法是深度学习 -&gt; 训练后得到具体模型</span></span></code></pre></div><p>注意最后一层的差别：AI、机器学习、深度学习是“方法或领域”的名称，模型是“训练结果”。当我们说“调用一个 AI 模型”时，实际是在给某个训练好的模型输入数据，让它按学到的规律输出结果。</p><h3 id="训练和推理有什么不同" tabindex="-1">训练和推理有什么不同 <a class="header-anchor" href="#训练和推理有什么不同" aria-label="Permalink to &quot;训练和推理有什么不同&quot;">​</a></h3><p><strong>训练（Training）</strong> 是让模型学习的阶段，<strong>推理（Inference）</strong> 是使用模型的阶段：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>训练：数据 + 学习目标 -&gt; 反复调整参数 -&gt; 得到模型</span></span>
<span class="line"><span>推理：参数固定的模型 + 新输入 -&gt; 输出结果</span></span></code></pre></div><p>训练需要准备数据（文本、图片、音频、代码、标注结果等），确定学习目标（例如预测下一个词、识别图片类别、生成图片），并用<strong>损失函数（Loss）</strong> 衡量模型输出与目标之间的差距，再据此调整模型内部的参数。</p><p>推理时参数不再变化。用户输入 Prompt、图片或其他上下文，模型根据已有参数生成结果。大多数普通用户接触到的都是推理：你无法查看或修改训练过程，能影响的主要是输入。</p><p>这个区分能解释两个常见现象：模型通常不知道训练截止之后发生的事情，因为它学到的规律已经固定在参数里；同一个模型对不同人回答质量不同，差别主要来自输入不同，而不是模型“看人下菜”。</p><h3 id="token-和上下文窗口为什么重要" tabindex="-1">Token 和上下文窗口为什么重要 <a class="header-anchor" href="#token-和上下文窗口为什么重要" aria-label="Permalink to &quot;Token 和上下文窗口为什么重要&quot;">​</a></h3><p><strong>Token</strong> 是模型处理文本的基本单位。它不一定等于一个字或一个词：中文、英文、标点、空格都可能被切成不同粒度，同一段文字在不同模型里的 Token 数也可能不同。</p><p><strong>上下文窗口（Context Window）</strong> 是模型一次能处理的 Token 范围：窗口越大，能装下的历史对话和长文档越多，计算量和成本也随之上升；会话过长时，较早的内容还可能被挤出窗口。上下文越长不代表效果一定越好，无关信息太多时，模型反而更难抓住重点。详细机制与调参影响见<a href="/llm/inference-decoding">推理与解码</a>。</p><h3 id="embedding-是什么-参数量能说明什么" tabindex="-1">Embedding 是什么，参数量能说明什么 <a class="header-anchor" href="#embedding-是什么-参数量能说明什么" aria-label="Permalink to &quot;Embedding 是什么，参数量能说明什么&quot;">​</a></h3><p><strong>Embedding（嵌入）</strong> 是把文本、图片或其他对象转换成<strong>向量（Vector）</strong>——一串可计算的数字——的表示方法。直观理解：意思相近的内容，向量之间的距离更近。常见用途：</p><ul><li>搜索相似文档。</li><li>推荐相关内容。</li><li>在 RAG（Retrieval-Augmented Generation，检索增强生成）中检索知识片段。</li><li>聚类和去重。</li></ul><p>Embedding 本身不回答问题，它更像“可计算的语义索引”。</p><p><strong>参数（Parameter）</strong> 是模型内部保存知识和规律的可调数字，训练过程就是不断调整它们。参数更多通常意味着表达能力更强，但也带来更高的训练和使用成本。</p><p>因此评价一个模型不要只看参数量，还要看：</p><ul><li>训练数据的质量和覆盖面。</li><li>架构与训练方法。</li><li>推理速度和成本。</li><li>上下文长度。</li><li>工具调用、结构化输出、多模态等能力。</li><li>是否适合你的具体任务。</li></ul><h3 id="生成式与判别式-模型的两种输出方式" tabindex="-1">生成式与判别式：模型的两种输出方式 <a class="header-anchor" href="#生成式与判别式-模型的两种输出方式" aria-label="Permalink to &quot;生成式与判别式：模型的两种输出方式&quot;">​</a></h3><p>按输出方式可以把常见模型分成两类。**判别式模型（Discriminative Model）**回答“这是哪类”：给定输入，判断它属于哪个类别或预测一个数值，输出是一个结论。判断邮件是否垃圾、识别照片里有没有人、预测明天的用电量，都是判别式任务——它们不创造新内容，只对给定的内容给出判断。**生成式模型（Generative Model）**则创造新内容：续写一段文字、画一张图、生成一段代码，输出是此前不存在的新样本。</p><p>可以类比为两种职业：判别式像阅卷老师，题目已经给定，他只负责打分和下结论；生成式像写作者，根据要求从零写出文章。同一个产品里两类经常协作：邮箱先用判别式模型决定“这封是不是垃圾邮件”，再用生成式模型帮你起草一封回复。</p><p>这个区分也把本站的两条主线挂到了同一个框架上：大语言模型是生成式的——逐个预测下一个 Token，本质是在创造文本序列；AI 绘画的扩散模型也是生成式的——从噪声逐步生成图像。判别式思路更多出现在传统机器学习里，例如<a href="/ai/machine-learning">机器学习入门</a>讲到的分类任务。生成式模型通常也能做判断类任务（让它读邮件并回答“是不是垃圾邮件”），但判断依据同样是学到的统计规律，精度并不自动超过专门训练的分类器。</p><h3 id="模型的能力边界从哪里来" tabindex="-1">模型的能力边界从哪里来 <a class="header-anchor" href="#模型的能力边界从哪里来" aria-label="Permalink to &quot;模型的能力边界从哪里来&quot;">​</a></h3><p>模型从训练数据中学习统计规律，这条出身决定了它的能力边界，至少有三条值得记住：</p><ul><li><strong>幻觉与有限的泛化</strong>：模型对没见过的情形会出错，而且常常错得很自信。生成式模型尤其明显：它按“什么样的输出最像训练数据”来生成，并没有内置“先查证再说”的环节，于是会产生看似合理却没有依据的内容——这类输出就是幻觉（术语见<a href="/glossary#hallucination">术语表</a>）。判别式模型同样会出错，只是形式是误判而不是编造：训练样本里没见过的新骗术，垃圾邮件过滤器就可能漏掉。</li><li><strong>知识截止（Knowledge Cutoff）</strong>：参数在训练结束时固定，模型“知道什么”停留在训练数据的时间下限，之后发生的事默认不在它脑子里（词条见<a href="/glossary#knowledge-cutoff">术语表</a>）。</li><li><strong>精确任务不是主场</strong>：模型按数据中的规律作答，不是在执行四则运算规则。它见过海量“3 加 5 等于 8”的句子，简单计算常常能对；但位数一多、步骤一长，靠“像不像”作答的错误率就会上升。涉及精确计算，更可靠的做法是交给计算器或程序执行，让模型做它擅长的部分——理解题意、拆解步骤、检查思路。</li></ul><p>一句话定位：<strong>模型不是数据库，也不是计算器</strong>。它不保证记住的事实都准确，也不保证计算精确无误；它擅长的是对语言和模式做灵活的理解、归纳与生成。落到 LLM 场景时这些边界如何表现，见<a href="/llm/basics">大模型入门</a>。</p><h3 id="一个-ai-系统的组成" tabindex="-1">一个 AI 系统的组成 <a class="header-anchor" href="#一个-ai-系统的组成" aria-label="Permalink to &quot;一个 AI 系统的组成&quot;">​</a></h3><p>产品里的 AI 很少只是一个模型。一个能持续使用的 AI 系统，通常包含四个环节：</p><ul><li><strong>数据</strong>：历史样本与标注，例如过去的邮件和“垃圾/正常”标记。数据质量决定模型上限，<a href="/ai/machine-learning">机器学习入门</a>讲的训练集、验证集、测试集划分就发生在这一环。</li><li><strong>模型</strong>：训练得到的参数加结构，是系统的核心部件，也是本站大部分页面的主角。</li><li><strong>推理服务（Inference Service）</strong>：把模型包装成能稳定响应请求的服务——接收输入、调用模型、返回结果，并控制延迟与成本。用户日常“使用 AI”打交道的大多是这一环，常见工具形态见<a href="/tools/common-tools">常用工具</a>。</li><li><strong>反馈收集</strong>：记录用户的纠正信号，例如把被你标成垃圾邮件的邮件存成新标注，回流到数据一环，供下一轮训练使用。</li></ul><p>四个环节连成闭环：数据训练出模型，模型部署成推理服务，服务在使用中产生反馈，反馈又变成新的数据。很多实际失败不在模型本身，而在两端——训练数据有偏差，或者反馈没人收集、收集了没人用。这也是为什么“换个更强的模型”并不总能解决问题。</p><h2 id="最小推演-邮件分类-手写规则还是让模型学" tabindex="-1">最小推演：邮件分类，手写规则还是让模型学 <a class="header-anchor" href="#最小推演-邮件分类-手写规则还是让模型学" aria-label="Permalink to &quot;最小推演：邮件分类，手写规则还是让模型学&quot;">​</a></h2><p>假设要把邮件自动分成“垃圾邮件”和“正常邮件”，先看 5 封邮件：</p><table tabindex="0"><thead><tr><th>邮件</th><th>明显特征</th><th>实际类别</th></tr></thead><tbody><tr><td>1</td><td>含“中奖”“限时”，陌生发件人</td><td>垃圾邮件</td></tr><tr><td>2</td><td>含“会议纪要”，同事发来</td><td>正常邮件</td></tr><tr><td>3</td><td>含“中奖”，来自常联系的票务平台</td><td>正常邮件</td></tr><tr><td>4</td><td>含“优惠”，来自熟悉的电商</td><td>正常邮件</td></tr><tr><td>5</td><td>无特殊关键词，但链接指向陌生网站</td><td>垃圾邮件</td></tr></tbody></table><p>路线一：手写规则。最自然的规则是“含‘中奖’就是垃圾邮件”——邮件 1 判对了，邮件 3 却被误判。补一条“可信发件人除外”，来自可信渠道但实为钓鱼的邮件又可能漏掉。邮件 5 不含任何关键词，只能继续添加“解析链接域名”之类越来越复杂的规则。例外情况永远比规则多。</p><p>路线二：从标注样本学习。把这 5 封（实际中是成千上万封）邮件连同正确答案交给学习算法，算法统计的是“哪些特征组合更常出现在垃圾邮件里”。“中奖”在垃圾邮件中高频出现，但也在少量正常邮件中出现，于是模型不会把它当成绝对信号，而是与发件人、链接、措辞等特征放在一起综合衡量。</p><p>两条路线的差别：手写规则必须穷举所有例外，规则之间还会互相冲突；学习方法不追求每条判断都有明确理由，而是让整体的错误率尽量低，并随着样本增加继续修正。局限也在这里：模型学到的是历史样本中的统计规律，垃圾邮件换了新写法、样本本身有偏差，它照样出错，而且通常说不出“为什么”。</p><p>这个推演只说明“规则难以穷举、从样本中学习可行”这个动机，不等于真实模型就是这样逐条数特征——实际模型的特征表示和计算过程要复杂得多。</p><h2 id="对比表" tabindex="-1">对比表 <a class="header-anchor" href="#对比表" aria-label="Permalink to &quot;对比表&quot;">​</a></h2><p>下表前三行从上到下逐层收窄，第 4 行是训练得到的产物，第 5 行是目前最常见的具体形态，最后两行按输出方式划分：</p><table tabindex="0"><thead><tr><th>概念</th><th>与其他概念的关系</th><th>典型例子</th><th>容易混淆的点</th></tr></thead><tbody><tr><td>AI</td><td>总称，覆盖一切让机器表现智能的方法</td><td>图像识别、下棋程序、聊天模型</td><td>不等于机器人，也不等于“会思考”</td></tr><tr><td>机器学习</td><td>AI 的子集，从数据中学规律</td><td>垃圾邮件过滤、房价预测</td><td>不写死规则，但必须依赖数据</td></tr><tr><td>深度学习</td><td>机器学习的子集，用多层神经网络</td><td>大语言模型、图像生成模型</td><td>“深度”指网络层数，不是想得深</td></tr><tr><td>模型</td><td>训练得到的产物（参数加结构）</td><td>某个具体的对话模型、分类模型</td><td>前三者是方法或领域，模型是结果</td></tr><tr><td>大语言模型（LLM）</td><td>用深度学习在海量文本上训练的模型</td><td>网页聊天助手背后的模型</td><td>回答流畅不代表内容正确</td></tr><tr><td>判别式模型</td><td>按输出方式划分：对给定输入给出判断或预测</td><td>垃圾邮件分类器、图像识别系统</td><td>只下结论，不创造新内容</td></tr><tr><td>生成式模型</td><td>按输出方式划分：创造新的文本或图像</td><td>大语言模型、AI 绘画模型</td><td>也能做判断类任务，但依据仍是统计规律</td></tr></tbody></table><p>判断一个产品属于哪一层，看它的核心方法而不是宣传用语。本站其余页面基本都围绕“模型”这一层展开。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li><strong>“AI 会像人一样思考”</strong>：目前主流模型学的是数据中的统计规律，没有人类式的理解和意识，换一种说法描述同一件事就可能让它出错。</li><li><strong>“AI 什么都懂”</strong>：模型会生成看似合理的内容，但可能事实错误，这类错误输出常被称为幻觉（Hallucination）。</li><li><strong>“模型越大越好”</strong>：任务简单时，小模型可能更快、更省资源，效果也足够；参数量只是能力的一个方面。</li><li><strong>“把资料全塞进上下文最好”</strong>：上下文需要筛选和组织，无关信息会干扰模型抓住重点。</li><li><strong>“联网就一定准确”</strong>：联网只是增加信息来源，不等于模型自动判断真假。</li><li><strong>“Token 就是一个字或一个词”</strong>：Token 的切分方式由具体模型决定，同一段文字在不同模型里的 Token 数可能不同。</li><li><strong>“AI 系统就是一个模型”</strong>：模型只是核心部件，数据质量、推理服务和反馈闭环同样决定实际效果；很多问题出在数据而不在模型，换更强的模型未必能解决。</li><li><strong>“生成式更先进，判别式要被淘汰”</strong>：两者解决的是不同问题，判断与创造互不替代；判断一封邮件是否垃圾，专门训练的判别式模型往往更小、更快、更稳。</li></ul><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><h3 id="_1-你在网页上使用一个对话助手-它和-ai、机器学习是什么关系" tabindex="-1">1. 你在网页上使用一个对话助手，它和 AI、机器学习是什么关系？ <a class="header-anchor" href="#_1-你在网页上使用一个对话助手-它和-ai、机器学习是什么关系" aria-label="Permalink to &quot;1. 你在网页上使用一个对话助手，它和 AI、机器学习是什么关系？&quot;">​</a></h3><details><summary>查看答案</summary><p>这个助手背后是一个训练好的模型。它是用机器学习方法（通常是深度学习）在海量数据上训练得到的，而机器学习是实现 AI 的主流途径。AI 是领域总称，机器学习是方法，模型是训练产物。</p></details><h3 id="_2-输入一段话并得到回答-这个过程属于训练还是推理-为什么模型通常不知道训练截止之后发生的事" tabindex="-1">2. 输入一段话并得到回答，这个过程属于训练还是推理？为什么模型通常不知道训练截止之后发生的事？ <a class="header-anchor" href="#_2-输入一段话并得到回答-这个过程属于训练还是推理-为什么模型通常不知道训练截止之后发生的事" aria-label="Permalink to &quot;2. 输入一段话并得到回答，这个过程属于训练还是推理？为什么模型通常不知道训练截止之后发生的事？&quot;">​</a></h3><details><summary>查看答案</summary><p>属于推理。推理阶段参数已经固定，模型只能使用训练时学到的规律，因此训练截止之后的新事件不在它的“记忆”里，除非系统额外接入联网检索或工具来补充信息。</p></details><h3 id="_3-为什么-参数量大-不能直接推出-模型一定更好" tabindex="-1">3. 为什么“参数量大”不能直接推出“模型一定更好”？ <a class="header-anchor" href="#_3-为什么-参数量大-不能直接推出-模型一定更好" aria-label="Permalink to &quot;3. 为什么“参数量大”不能直接推出“模型一定更好”？&quot;">​</a></h3><details><summary>查看答案</summary><p>参数量只代表表达能力的一个方面。最终效果还取决于训练数据质量、架构与训练方法，以及模型与任务是否匹配；参数更大通常也意味着更慢、更贵。评价模型应该结合具体任务和成本。</p></details><h3 id="_4-判断-这封邮件是不是垃圾邮件-和-帮我起草一封回复-分别属于判别式还是生成式任务" tabindex="-1">4. 判断“这封邮件是不是垃圾邮件”和“帮我起草一封回复”，分别属于判别式还是生成式任务？ <a class="header-anchor" href="#_4-判断-这封邮件是不是垃圾邮件-和-帮我起草一封回复-分别属于判别式还是生成式任务" aria-label="Permalink to &quot;4. 判断“这封邮件是不是垃圾邮件”和“帮我起草一封回复”，分别属于判别式还是生成式任务？&quot;">​</a></h3><details><summary>查看答案</summary><p>前者是判别式任务：对给定输入输出一个类别判断，不产生新内容。后者是生成式任务：模型创造出一封原本不存在的回复。同一个产品里两类经常协作，例如邮箱先用判别式模型过滤垃圾邮件，再用生成式模型帮你起草回复。</p></details><h3 id="_5-同事说-我们已经买了最强的模型-ai-项目稳了-。用-一个-ai-系统的组成-说明他可能漏掉了什么。" tabindex="-1">5. 同事说“我们已经买了最强的模型，AI 项目稳了”。用“一个 AI 系统的组成”说明他可能漏掉了什么。 <a class="header-anchor" href="#_5-同事说-我们已经买了最强的模型-ai-项目稳了-。用-一个-ai-系统的组成-说明他可能漏掉了什么。" aria-label="Permalink to &quot;5. 同事说“我们已经买了最强的模型，AI 项目稳了”。用“一个 AI 系统的组成”说明他可能漏掉了什么。&quot;">​</a></h3><details><summary>查看答案</summary><p>模型只是系统的一个部件。他可能漏掉了：训练数据是否充足、有代表性（数据）；服务能否稳定响应、控制延迟与成本（推理服务）；以及用户反馈有没有被收集并回流成新的训练数据（反馈收集）。两端任一环节缺失，强模型也发挥不出效果。</p></details><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to &quot;关联阅读&quot;">​</a></h2><ul><li><strong>主题地图：</strong> <a href="/guide/getting-started">学习地图</a>帮助你按目标组合页面。</li><li><strong>同主题：</strong> <a href="/ai/machine-learning">机器学习入门</a>展开数据、训练与评估，回答“模型具体怎么学”。</li><li><strong>延伸方向：</strong> <a href="/llm/basics">大模型入门</a>说明这些基础概念怎样体现在 LLM 中。</li><li><strong>AI 绘画方向：</strong> <a href="/concepts/how-it-works">基本原理</a>展示生成式模型在图像生成上的具体形态。</li></ul><h2 id="官方或原始资料来源" tabindex="-1">官方或原始资料来源 <a class="header-anchor" href="#官方或原始资料来源" aria-label="Permalink to &quot;官方或原始资料来源&quot;">​</a></h2><ul><li><a href="https://en.wikipedia.org/wiki/Artificial_intelligence" target="_blank" rel="noreferrer">Wikipedia：Artificial Intelligence</a>：AI 领域的定义、历史与主要分支。</li><li><a href="https://en.wikipedia.org/wiki/Machine_learning" target="_blank" rel="noreferrer">Wikipedia：Machine Learning</a>：机器学习的正式定义与常见方法分类。</li><li><a href="https://en.wikipedia.org/wiki/Deep_learning" target="_blank" rel="noreferrer">Wikipedia：Deep Learning</a>：深度学习与神经网络关系的概览。</li><li><a href="https://developers.google.com/machine-learning/intro-to-ml/what-is-ml" target="_blank" rel="noreferrer">Google：What is Machine Learning?</a>：Google 机器学习入门课程的官方定义页。</li><li><a href="https://plato.stanford.edu/entries/artificial-intelligence/" target="_blank" rel="noreferrer">Stanford Encyclopedia of Philosophy：Artificial Intelligence</a>：斯坦福哲学百科的 AI 条目，适合深入了解概念边界。</li><li><a href="https://developers.google.com/machine-learning/crash-course" target="_blank" rel="noreferrer">Google：Machine Learning Crash Course</a>：官方课程入口，含分类、评估与生成式 AI 概念模块。</li><li><a href="https://developers.google.com/machine-learning/glossary" target="_blank" rel="noreferrer">Google：Machine Learning Glossary</a>：官方术语表，可查判别式模型、生成式模型等词条的正式定义。</li><li><a href="https://hai.stanford.edu/ai-index" target="_blank" rel="noreferrer">Stanford HAI：AI Index Report</a>：斯坦福发布的年度 AI 发展报告，覆盖模型能力、成本与局限的公开数据。</li></ul>`,70)])])}const u=t(l,[["render",n]]);export{c as __pageData,u as default};
